/** DO NOT EDIT: generated by `python -m radar model generate` from contracts/model/views.json: the public read model. */

/** Opaque id: the entity's three-letter prefix (entities.json) plus 10 lowercase Crockford base32 characters. */
export type EntityId = string;

/** Id of a registry item (a Term, Unit, Dimension, SpecDefinition or Category). */
export type TermId = string;

/** Who made a change or filed a proposal: a person (the founder or a reader), an agent, or an import. */
export type ActorKind = "human" | "agent" | "import";

/** How a search ranked its products: by the words they hold, or, when no word matched, by closeness in meaning. */
export type Ranking = "words" | "meaning";

/** Where a proposal stands in the review queue: waiting, applied, refused, or undone after it was applied. */
export type ProposalStatus = "suggested" | "approved" | "rejected" | "retracted";

/** What the review queue's audit log records done to a proposal. */
export type ProposalAction = "submit" | "edit" | "approve" | "reject" | "retract";

/** What a proposal of a bundle does to the records the store holds, riskiest first: withdraws one, changes one, or only adds. */
export type Risk = "withdraws" | "changes" | "adds";

/** The event that files a proposal: a record added, changed, merged or withdrawn, a reader's report, a quality check, a news draft, a rollback. */
export type FilesOn = "create" | "update" | "merge" | "retract" | "report" | "quality" | "feed" | "rollback";

/** An AI use in the system: ask, research, datasheet extraction, news drafting, or all uses together. */
export type Use = "all" | "ask" | "research" | "datasheet" | "draft";

/** What an outside agent token permits: reading catalog data, or reading and proposing changes. */
export type Scope = "read" | "propose";

/** Where an agent token stands: active, expired past its date, or revoked by the founder. */
export type Standing = "active" | "expired" | "revoked";

/** Where a research run stands: running; done, every page in reach read; partial, its page or time budget spent with pages left; blocked, no page in reach read; stopped by the founder, stopped by an AI cap, or failed. */
export type ResearchStatus = "running" | "done" | "partial" | "blocked" | "cancelled" | "capped" | "failed";

/** One step of a research run: a page or file read or skipped, a proposal filed, rejected, or run ended. */
export type ResearchStep = "read" | "skipped" | "filed" | "media" | "datasheet" | "rejected" | "ended";

/** BCP-47 language tag to text; en is required and is the fallback. */
export type LocalizedText = Readonly<Record<string, string>> & { readonly en: string };

/** Calendar date with an explicit precision, so no date claims more exactness than its source. */
export interface PartialDate {
  readonly value: string;
  readonly precision: "year" | "half" | "quarter" | "month" | "day";
  readonly approximate?: boolean;
}

/** Price with ISO 4217 currency and the date it was observed. */
export interface Price {
  readonly amount: number;
  readonly currency: string;
  readonly as_of: PartialDate;
}

/** One sentence of a news article and what it rests on: at least one product, organization or source. */
export interface FeedSentence {
  readonly text: LocalizedText;
  readonly cites: readonly EntityId[];
}

/** A registry term as pages show it: its id and label. */
export interface TermRef {
  readonly id: string;
  readonly label: LocalizedText;
}

/** A pipeline stage or a domain, with its words. */
export interface TermEntry {
  readonly id: string;
  readonly label: LocalizedText;
  readonly description: LocalizedText;
}

/** A number in the spec's one published unit (its symbol). */
export interface ViewQuantity {
  readonly value: number;
  readonly unit?: string;
}

/** A range in the spec's one published unit (its symbol). */
export interface ViewRange {
  readonly min: number;
  readonly max: number;
  readonly unit?: string;
}

/** A published spec value, tagged by kind. */
export type ViewValue = { readonly quantity: ViewQuantity } | { readonly range: ViewRange } | { readonly term: TermRef } | { readonly terms: readonly TermRef[] } | { readonly boolean: boolean } | { readonly string: string } | { readonly none: TermRef };

/** A spec's registry label, the unit symbol its values are published in, and which way a value is better. */
export interface SpecLabel {
  readonly label: LocalizedText;
  readonly unit?: string;
  readonly better?: "higher" | "lower";
}

/** One filter option and how many products of the listing offer it. */
export interface FacetOption {
  readonly id: string;
  readonly label: LocalizedText;
  readonly count: number;
}

/** A CategoryProfile filter with its counted options, and how many of the listing's products publish its spec. */
export interface FacetView {
  readonly id: string;
  readonly spec_key: string;
  readonly label: LocalizedText;
  readonly description?: LocalizedText;
  readonly kind: "enum" | "multi" | "number" | "boolean";
  readonly count: number;
  readonly unit?: string;
  readonly options: readonly FacetOption[];
  readonly min?: number;
  readonly max?: number;
}

/** A CategoryProfile's spec keys in display order: the core specs, then the detail specs. */
export interface SectionKeys {
  readonly core: readonly string[];
  readonly detail: readonly string[];
}

/** A category as browse shows it, with its listing size in products and pages; its facets are on its listing pages. */
export interface CategoryEntry {
  readonly id: string;
  readonly label: LocalizedText;
  readonly description: LocalizedText;
  readonly domain: string;
  readonly pipeline: readonly string[];
  readonly glyph: string;
  readonly sections: SectionKeys;
  readonly products: number;
  readonly pages: number;
  readonly component_hub?: string;
}

/** An organization as a link shows it. */
export interface OrgBrief {
  readonly id: string;
  readonly slug: string;
  readonly name: string;
  readonly country?: string;
}

/** A product as a card shows it; `specs` holds the published values a card or a listing filter needs. */
export interface ProductCard {
  readonly id: string;
  readonly slug: string;
  readonly name: string;
  readonly kind: string;
  readonly vendor: string;
  readonly vendor_name: string;
  readonly category: string;
  readonly summary?: LocalizedText;
  readonly status?: TermRef;
  readonly tags: readonly string[];
  readonly specs: Readonly<Record<string, ViewValue>>;
  readonly thumbnail_url?: string;
}

/** How many products, organizations and categories the read model publishes. */
export interface IndexCounts {
  readonly products: number;
  readonly organizations: number;
  readonly categories: number;
}

/** The index: what home, browse and search read. */
export interface IndexView {
  readonly data_as_of?: string;
  readonly counts: IndexCounts;
  readonly pipeline_stages: readonly TermEntry[];
  readonly domains: readonly TermEntry[];
  readonly categories: readonly CategoryEntry[];
  readonly spec_definitions: Readonly<Record<string, SpecLabel>>;
  readonly spec_groups: Readonly<Record<string, LocalizedText>>;
  readonly tags: readonly TermRef[];
  readonly search: SearchSettings;
  readonly news: readonly FeedBrief[];
  readonly organizations: readonly OrgBrief[];
  readonly products: readonly ProductCard[];
}

/** The registry: the index without its cards and organizations, which every page needs to label things. */
export interface RegistryView {
  readonly data_as_of?: string;
  readonly counts: IndexCounts;
  readonly pipeline_stages: readonly TermEntry[];
  readonly domains: readonly TermEntry[];
  readonly categories: readonly CategoryEntry[];
  readonly spec_definitions: Readonly<Record<string, SpecLabel>>;
  readonly spec_groups: Readonly<Record<string, LocalizedText>>;
  readonly tags: readonly TermRef[];
  readonly search: SearchSettings;
  readonly news: readonly FeedBrief[];
}

/** One page of a category's listing, with the category's facet counts. */
export interface CategoryPage {
  readonly category: string;
  readonly page: number;
  readonly pages: number;
  readonly next?: string;
  readonly facets: readonly FacetView[];
  readonly products: readonly ProductCard[];
}

/** A source as a page cites it. */
export interface SourceView {
  readonly id: string;
  readonly type: TermRef;
  readonly url?: string;
  readonly title?: string;
  readonly retrieved_at: string;
}

