/** One field a version changed, each value in JSON text (absent where the field was absent). */
export interface FieldChangeView {
  readonly path: string;
  readonly before?: string;
  readonly after?: string;
}

/** One recorded version of a record, newest first in its HistoryView: the record, the spec key it carries if any, and what the version changed. */
export interface HistoryEntry {
  readonly entity: string;
  readonly spec?: string;
  readonly version: number;
  readonly recorded_at: string;
  readonly actor_kind: ActorKind;
  readonly actor: string;
  readonly reason: string;
  readonly changed: readonly FieldChangeView[];
  readonly sources: readonly SourceView[];
  readonly proposal?: string;
  readonly correlation_id: string;
}

/** A record's versions; a product's are its own and those of the public records about it, each with more than one. */
