/** The catalog's Sources and media Documents a `radar source search` finds, each list newest first. */
export interface FoundSources {
  readonly sources: readonly SourceView[];
  readonly documents: readonly DocumentView[];
}

export const ENTITY_KINDS = {
  Organization: { prefix: "org", collection: "organizations" },
  OrgRelation: { prefix: "orl", collection: "org_relations" },
  Product: { prefix: "prd", collection: "products" },
  ProductOrgRole: { prefix: "por", collection: "product_org_roles" },
  Name: { prefix: "nam", collection: "names" },
  ProductVersion: { prefix: "ver", collection: "product_versions" },
  Offering: { prefix: "off", collection: "offerings" },
  Identifier: { prefix: "idn", collection: "identifiers" },
  Claim: { prefix: "clm", collection: "claims" },
  Source: { prefix: "src", collection: "sources" },
  Document: { prefix: "doc", collection: "documents" },
  LifecycleEvent: { prefix: "evt", collection: "lifecycle_events" },
  ObservedStatus: { prefix: "obs", collection: "observed_statuses" },
  Relation: { prefix: "rel", collection: "relations" },
  AltName: { prefix: "aln", collection: "alt_names" },
  EvalQuery: { prefix: "evq", collection: "eval_queries" },
  FeedItem: { prefix: "nws", collection: "feed_items" },
  AiCap: { prefix: "cap", collection: "ai_caps" },
  Change: { prefix: "chg", collection: "changes" },
} as const;

export type EntityKind = keyof typeof ENTITY_KINDS;

const _PREFIX_TO_KIND: Readonly<Record<string, EntityKind>> = Object.fromEntries(
  // Justification (typed boundary): Object.entries widens keys to string; keys are EntityKind.
  Object.entries(ENTITY_KINDS).map(([kind, spec]) => [spec.prefix, kind as EntityKind]),
);

/** The entity kind an id names, by its prefix. */
export function kindOf(id: string): EntityKind | undefined {
  return _PREFIX_TO_KIND[id.split("_")[0]];
}
